#include "ksStateDspFactoryTransferTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StateDspFactoryTransferTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;auto stream=[&](unsigned value,unsigned count,bool byte,unsigned readClocks){const uint32_t descriptor=(byte?0x08000000u:0)|(value&255);T task{T::Kind::Stream,descriptor,uint16_t(count)};unsigned reads=0,writes=0,primes=0,clocks=0;const unsigned effective=count?count:65536;auto read=[&](bool b){check(b==byte&&task.byteOffset()==reads*(byte?1:2),"Sample late source/width");++reads;return value;};while(!task.complete()){if(task.awaitingChild()){if(task.child()==T::Child::Prime)++primes;else{check(task.child()==T::Child::Write,"Sample child kind");uint32_t sample=byte?uint16_t(uint8_t(value+128))<<8:uint16_t(value);check(task.payload()==(sample<<16|(value&255)),"Sample encodedpayload/trailingbyte");++writes;}check(task.resumeChild(),"Sample childresume");continue;}const auto c=task.nextClocks(readClocks),n=reads+writes;check(!task.advanceBefore(c-1,read,readClocks)&&n==reads+writes,"Sample earlyeffect");check(task.advanceBefore(c,read,readClocks)==c,"Sample admission");clocks+=c;}check(primes==1&&reads==effective&&writes==effective&&task.byteOffset()==effective*(byte?1:2)&&clocks==55+effective*(byte?43:31+readClocks),"Sample counts/clocks");check(!task.resumeChild(),"Sample lifecycle");++cases;};for(unsigned value=0;value<65536;++value)for(bool byte:{false,true})stream(value,1,byte,value&1?3:6);for(unsigned count:{0u,1u,2u,255u,256u,1024u,65535u})for(bool byte:{false,true})for(unsigned clocks:{3u,6u})stream(0x80ff,count,byte,clocks);
for(unsigned first=0;first<256;++first){T task{T::Kind::Poll};unsigned polls=0,clocks=0;auto read=[](bool){return 0;};while(!task.complete()){if(task.awaitingChild()){check(task.child()==T::Child::ReadStatus,"Poll child");task.resumeChild(uint8_t(polls++?128:first));continue;}auto c=task.nextClocks();check(!task.advanceBefore(c-1,read)&&task.advanceBefore(c,read)==c,"Poll deadline/admission");clocks+=c;}check(polls==(first==128?1:2)&&clocks==32*polls+17,"Readystatus retry/clocks");++cases;}std::cout<<"PASS: "<<cases<<" complete DSPfactory transfers,all16bitsamples+bytebias/trailer/readwidth/wrapped65536counts/readinessallbytes/exactpayloads/deadlines+clocks\n";return 0;}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}
